export const labelFor = (status) => {
  switch (status) {
    case 'a':
      return 'Alpha'
    case 'b':
      return 'Beta'
    default:
      break
  }
}

export const abortable = (fn) => {
  // @ts-expect-error -- upstream types omit `signal`; tracked in the library
  return fn({ signal: null })
}

export const labelFor = (status) => {
  switch (status) {
    case 'a':
      return 'Alpha'
    default: {
      const _exhaustive: never = status
      throw new Error(`Unhandled status: ${status}`)
    }
  }
}

export const parseOrder = (raw) => {
  const body = JSON.parse(raw) as unknown
  if (!isOrder(body)) throw new Error('invalid order')
  return body
}

export const profileOf = (id, cache) => {
  const user = cache.get(id)!.profile
  return user
}

export const totalOf = (order) => {
  const total = (order as any).grandTotal
  return total
}
